check_code:
syn={"Difficult":{"Complex","Hard"}}
opts={"A":"Trivial","B":"Imaginary","C":"Complex","D":"Wrong"}
fit=[k for k,v in opts.items() if v in syn["Difficult"]]
assert fit==["C"]

opts={"A":"TYTYTY","B":"YTYTYT","C":"TTYYTT","D":"TYTYYT"}
pat="Y_Y__Y_T_Y_Y"
def fill(o):
    it=iter(o); return "".join(next(it) if c=="_" else c for c in pat)
fit=[k for k,o in opts.items() if fill(o)=="YTY"*4]
assert fit==["D"]

def enc(w):
    return "".join(chr((28-(ord(c)-64)-1)%26+65) for c in w)
assert enc("FIGURE")=="VSUGJW" and enc("COPIED")=="YMLSWX"
v=enc("BLANKET")
opts={"A":"ZPMNQHW","B":"ZPANQHW","C":"ZPNAQWH","D":"ZPANQWH"}
assert v==opts["D"]
assert all(v!=x for k,x in opts.items() if k!="D")
